def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == 2:
            digits.append('-')
            n = (n // 3) + 1
        else:
            digits.append(str(remainder))
            n //= 3
    return ''.join(digits[::-1])
