def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n: int) -> int:
        return n.bit_count()

    # Using the inclusion-exclusion principle for bit counting in ranges
    def bit_sum(n: int) -> int:
        total = 0
        power_of_2 = 1
        while power_of_2 <= n:
            msb = (n // power_of_2) * power_of_2
            next_msb = msb + power_of_2
            total += ((msb >> 1) * power_of_2) + min(max(n - next_msb + 1, 0), power_of_2)
            power_of_2 <<= 1
        return total

    return bit_sum(hi) - bit_sum(lo - 1)
