@lru_cache(None)
def lcs(i: int, j: int) -> str:
    if i == len(a) or j == len(b):
        return ""
    elif a[i] == b[j]:
        return a[i] + lcs(i + 1, j + 1)
    else:
        return max(lcs(i + 1, j), lcs(i, j + 1), key=lambda x: (-len(x), x))

def smallest_lcs(a: str, b: str) -> str:
    global a, b
    a, b = sorted([a, b])
    return lcs(0, 0)
