import re

def tidy_punctuation(text: str) -> str:
    # Step 1: Replace runs of whitespace with a single space and strip leading/trailing spaces
    text = re.sub(r'\s+', ' ', text).strip()

    # Step 2: Ensure each specified punctuation mark is preceded by a space
    for char in ",.!:?":
        text = re.sub(f'({char})', f' {char}', text)

    # Step 3: Add a space after each specified punctuation mark if followed by a letter
    for char in ",.!:?":
        text = re.sub(f'{char}([a-zA-Z])', f'{char} \\1', text)

    # Step 4: Capitalize the first character and after .,!?
    def capitalize_match(match):
        return match.group(0).upper()

    text = re.sub(r'^|(?<=[.!?])\s*([a-z])', capitalize_match, text)

    return text

