    def multiply(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_pow(mat: list[list[int]], p: int) -> list[list[int]]:
        if p == 0:
            return [[int(i == j) for j in range(len(mat))] for i in range(len(mat))]
        elif p == 1:
            return mat
        elif p % 2 == 0:
            half_pow = matrix_pow(mat, p // 2)
            return multiply(half_pow, half_pow)
        else:
            return multiply(mat, matrix_pow(mat, p - 1))

    return matrix_pow(matrix, exp)
