from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    queue = deque([(start, False, 0)])  # (current position, has_broken_wall, moves)
    visited = set()

    while queue:
        (x, y), has_broken_wall, moves = queue.popleft()
        if (x, y, has_broken_wall) in visited:
            continue
        visited.add((x, y, has_broken_wall))

        if (x, y) == end:
            return moves

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                if grid[nx][ny] == '.':
                    queue.append(((nx, ny), has_broken_wall, moves + 1))
                elif not has_broken_wall:
                    queue.append(((nx, ny), True, moves + 1))

    return -1
