from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start):
        queue = deque([start + (False,)])
        visited = set()
        while queue:
            x, y, broke = queue.popleft()
            if (x, y, broke) in visited:
                continue
            visited.add((x, y, broke))
            if grid[x][y] == 'E':
                return True
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols:
                    if grid[nx][ny] == '.':
                        queue.append((nx, ny, broke))
                    elif not broke:
                        queue.append((nx, ny, True))
        return False

    start_x, start_y = next((i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 'S')
    result = bfs((start_x, start_y))
    return -1 if not result else 1
