from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    blocked = set((r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n)

    def is_valid(board, row, col):
        for i in range(row):
            if board[i][col] == 1:
                return False
            if col - (row - i) >= 0 and board[i][col - (row - i)] == 1:
                return False
            if col + (row - i) < n and board[i][col + (row - i)] == 1:
                return False
        return True

    def backtrack(row=0, count=0):
        if row == n:
            return 1
        for col in range(n):
            if (row, col) not in blocked and is_valid(board, row, col):
                board[row][col] = 1
                count += backtrack(row + 1)
                board[row][col] = 0
        return count

    board = [[0] * n for _ in range(n)]
    return backtrack()
