from typing import List, Tuple

def is_valid(board: List[List[bool]], row: int, col: int) -> bool:
    n = len(board)
    for i in range(n):
        if board[row][i] or board[i][col]:
            return False
        if 0 <= row + col - i < n and board[row + col - i][i]:
            return False
        if 0 <= row - col + i < n and board[row - col + i][i]:
            return False
    return True

def backtrack(board: List[List[bool]], row: int, n: int, blocked: Set[Tuple[int, int]]) -> int:
    if row == n:
        return 1
    count = 0
    for col in range(n):
        if (row, col) not in blocked and is_valid(board, row, col):
            board[row][col] = True
            count += backtrack(board, row + 1, n, blocked)
            board[row][col] = False
    return count

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1
    blocked_set = set(blocked)
