            return 1
        count = 0
        for i in range(n):
            if (i, col) not in blocked and is_valid(board, i, col):
                board[i][col] = 1
                count += solve(board, col + 1)
                board[i][col] = 0
        return count

    if n == 0:
        return 1
    board = [[0 for _ in range(n)] for _ in range(n)]
    return solve(board, 0)
