import operator

def evaluate_expression(expression: str) -> float:
    tokens = []
    i = 0
    while i < len(expression):
        if expression[i].isspace():
            i += 1
            continue
        elif expression[i] == '(':
            tokens.append(expression[i])
        elif expression[i] == ')':
            while tokens[-1] != '(':
                tokens.append(tokens.pop())
            tokens.pop()
        elif expression[i].isdigit() or expression[i] == '.':
            j = i
            while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            tokens.append(float(expression[i:j]))
            i = j - 1
        else:
            op = expression[i]
            while (tokens and tokens[-1] != '(' and
                   {'+', '-': 1, '*': 2, '/': 2, '**': 3}[op] <=
                   {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}[tokens[-1]]):
                tokens.append(tokens.pop())
            tokens.append(op)
        i += 1

    while len(tokens) > 1:
        right = tokens.pop()
        op = tokens.pop()
        left = tokens.pop()
        if op == '+':
            tokens.append(operator.add(left, right))
        elif op == '-':
            tokens.append(operator.sub(left, right))
        elif op == '*':
            tokens.append(operator.mul(left, right))
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            tokens.append(operator.truediv(left, right))
        elif op == '**':
            tokens.append(operator.pow(left, right))

