from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    queue = deque([(start, False, 0)])  # (current position, has_broken, steps)
    visited = set()

    while queue:
        (x, y), has_broken, steps = queue.popleft()
        if (x, y, has_broken) in visited:
            continue
        visited.add((x, y, has_broken))

        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                if grid[nx][ny] == '.':
                    queue.append(((nx, ny), has_broken, steps + 1))
                elif not has_broken:
                    queue.append(((nx, ny), True, steps + 2))

    return -1
