    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    discovery = [-1] * n
    lowlink = [0] * n
    bridges = set()
    time = 0

    for i in range(n):
        if discovery[i] == -1:
            dfs(i, -1)

    return sorted(list(bridges))
