from collections import defaultdict, deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    queue = deque([(source, 1)])
    visited[source] = True

    while queue:
        current, path_count = queue.popleft()

        if current == target:
            return path_count

        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append((neighbor, path_count))

    return 0
