from collections import defaultdict

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    graph = defaultdict(list)
    in_degree = [0] * n

    for u, v in pairs:
        if u != v:
            graph[u].append(v)
            in_degree[v] += 1

    queue = [u for u in range(n) if in_degree[u] == 0]
    result = []

    while queue:
        if len(queue) > 1:
            queue.sort()
        u = queue.pop(0)
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return result if len(result) == n else []
