import math

def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a: int, b: int) -> Tuple[int, int, int]:
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def lcm(a: int, b: int) -> int:
        return abs(a*b) // math.gcd(a, b)

    total_lcm = 1
    for _, m in congruences:
        total_lcm = lcm(total_lcm, m)

    x = 0
    for r, m in congruences:
        p = total_lcm // m
        gcd, inv, _ = extended_gcd(p, m)
        if gcd != 1:
            return None
        x += r * inv * p

    return (x % total_lcm, total_lcm)
