from typing import List

def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r: int, c: int) -> bool:
        return 0 <= r < rows and 0 <= c < cols

    def topple(r: int, c: int) -> None:
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                grid[nr][nc] += 1

    while True:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] >= 4:
                    changed = True
                    grid[r][c] -= 4
                    topple(r, c)
        if not changed:
            break

    return grid
