def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    sizes.sort(reverse=True)
    bins = []

    for size in sizes:
        if size > capacity:
            raise ValueError("An item is larger than the bin capacity.")

        placed = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
