from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def chinese_remainder_theorem(congruences):
        total = 0
        prod = reduce(lcm, [m for _, m in congruences])
        for rem, mod in congruences:
            p = prod // mod
            total += rem * pow(p, -1, mod) * p
        return total % prod

    try:
        x = chinese_remainder_theorem(congruences)
        return (x, reduce(lcm, [m for _, m in congruences]))
    except ValueError:
        return None
