def subsets_with_sum(nums: List[int], k: int) -> List[List[int]]:
    def backtrack(start: int, current_subset: List[int], remaining_sum: int):
        if remaining_sum == 0:
            result.append(current_subset[:])
            return
        for i in range(start, len(nums)):
            if nums[i] > remaining_sum:
