from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if not sizes:
        return []

    sizes.sort(reverse=True)
    bins = []

    for size in sizes:
        if size > capacity:
            raise ValueError("An element is larger than the bin capacity.")

        placed = False
        for bin_ in bins:
            if sum(bin_) + size <= capacity:
                bin_.append(size)
                placed = True
                break

        if not placed:
            bins.append([size])

    return bins
