def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number):
        raise ValueError("Invalid input")

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_value = 0
    power = 0
    for digit in reversed(number):
        if '0' <= digit <= '9':
            value = ord(digit) - ord('0')
        else:
            value = ord(digit.lower()) - ord('a') + 10
        decimal_value += value * (from_base ** power)
        power += 1

    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result = chr(remainder + ord('0')) + result
        else:
            result = chr(remainder - 10 + ord('a')) + result
        decimal_value //= to_base

    if is_negative:
        result = "-" + result

    return result
