        return re.sub(r'""', '"', field.strip('"'))

    def parse_unquoted_field(field):
        return field

    result = []
    lines = text.split('\n')
    for line in lines:
        if not line:
            result.append([''])
            continue
        fields = re.split(r'(,\"|(?<!")\n)', line)
