import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_quoted_field(match):
        return match.group(1).replace('""', '"')

    def parse_unquoted_field(match):
        return match.group(0)

    pattern = re.compile(r'"([^"]*(?:""[^"]*)*)"|([^,]+)')
    result = []
    current_record = []

    for match in pattern.finditer(text):
        if match.group(1) is not None:
            current_record.append(parse_quoted_field(match))
        elif match.group(2) is not None:
            current_record.append(parse_unquoted_field(match))

        if len(current_record) == 1 and current_record[0] == '':
            continue

        if '\n' in current_record[-1]:
            result.append(current_record)
            current_record = []

    if current_record:
        result.append(current_record)

    return result
