            standings[away][0] += 1

        standings[home][1] += home_goals
        standings[home][2] += away_goals
        standings[away][1] += away_goals
        standings[away][2] += home_goals

    return sorted([(team, *standings[team]) for team in standings], key=lambda x: (-x[1], -x[2], -x[3], x[0]))
