                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    # Directions for up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([start])
    visited = set([start])
