from collections import deque

def min_slides(grid: list[str]) -> int:
    n, m = len(grid), len(grid[0])
    start, end = None, None

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] != '#'

    def slide(x, y, dx, dy):
        while is_valid(x + dx, y + dy):
            x += dx
            y += dy
        return x, y

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (x, y), steps = queue.popleft()

        if (x, y) == end:
            return steps

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = slide(x, y, dx, dy)
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

    return -1
