from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None

    # Find the start and end positions
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    # Directions for up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([start])
    visited = set([start])
    distance = {start: 0}

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return distance[(x, y)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            # Check if the next position is within bounds and not a wall
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                new_pos = (nx, ny)

                # Slide the piece until hitting a wall or the edge
                while 0 <= nx + dx < rows and 0 <= ny + dy < cols and grid[nx + dx][ny + dy] != '#' and (nx + dx, ny + dy) != new_pos:
                    nx += dx
                    ny += dy

                if new_pos not in visited:
                    visited.add(new_pos)
                    distance[new_pos] = distance[(x, y)] + 1
                    queue.append(new_pos)

    return -1
