def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    standings = defaultdict(lambda: [0, 0, 0])

    for home, away, home_goals, away_goals in results:
        standings[home][0] += 1
        standings[away][0] += 1
        if home_goals > away_goals:
            standings[home][1] += 3
            standings[away][1] += 0
        elif home_goals < away_goals:
            standings[home][1] += 0
            standings[away][1] += 3
        else:
            standings[home][1] += 1
            standings[away][1] += 1

        standings[home][2] += home_goals
        standings[away][2] += away_goals

    for team, stats in standings.items():
        stats.append(stats[2] - stats[3])

    sorted_standings = sorted(standings.items(), key=lambda x: (-x[1][1], -x[1][4], -x[1][2], x[0]))

