def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not url.lower().startswith('https://'):
        return False

    # Remove query parameters and fragment identifier
    url = re.split(r'[?#]', url)[0]

    # Check for backslashes, spaces, and control characters
    if '\\' in url or ' ' in url or any(ord(c) < 32 or ord(c) == 127 for c in url):
        return False

    # Split URL into components
    parts = url[len('https://'):].split('/')
    if len(parts) > 1:
        host_port = parts[0]
    else:
        host_port = parts[0]

    # Extract host and port
    host, _, port = host_port.partition(':')
    if port and int(port) != 443:
        return False

    # Validate host format
    if '.' in host:
        labels = host.rstrip('.').split('.')
        if len(labels) < 2 or labels[-1].isdigit():
            return False
        if any(not label.isalnum() or '-' in label[:-1] or not label[-1].isalpha() for label in labels):
            return False
    elif host.lower() in ['localhost', 'localhost.']:
        return False

    return True
