import re

def is_allowed_webhook(url: str) -> bool:
    # Regular expression for validating the URL
    pattern = re.compile(
        r'^(?:https?://)?'  # Optional scheme
        r'(?:[^\s@:/]+@)?'  # Optional user:password or user@
        r'(?P<host>[^:/?#]+)'  # Host part
        r'(?::\d{1,5})?'  # Optional port
        r'[/?#].*$', re.IGNORECASE)

    match = pattern.match(url)
    if not match:
        return False

    host = match.group('host')
    if host.endswith('.'):
        host = host[:-1]

    if host.lower() == 'localhost':
        return False

