def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    def rotate_ring(ring: list[int], k: int) -> list[int]:
        k %= len(ring)
        return ring[-k:] + ring[:-k]

    for i in range((n + 1) // 2):
        ring = []
        for j in range(i, n - i):
            ring.append(result[i][j])
        for j in range(i + 1, n - i):
            ring.append(result[j][n - i - 1])
        for j in range(n - i - 2, i - 1, -1):
            ring.append(result[n - i - 1][j])
        for j in range(n - i - 2, i, -1):
            ring.append(result[j][i])

        rotated_ring = rotate_ring(ring, k)

        idx = 0
        for j in range(i, n - i):
            result[i][j] = rotated_ring[idx]
            idx += 1
        for j in range(i + 1, n - i):
            result[j][n - i - 1] = rotated_ring[idx]
            idx += 1
        for j in range(n - i - 2, i - 1, -1):
            result[n - i - 1][j] = rotated_ring[idx]
            idx += 1
        for j in range(n - i - 2, i, -1):
            result[j][i] = rotated_ring[idx]
            idx += 1

    return result
