def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            while waiting and waiting[0][0] == item and stock[item] + waiting[0][1] >= quantity:
                _, w_quantity = waiting.pop(0)
                quantity -= w_quantity
                stock[item] += w_quantity
            if quantity > 0:
                stock[item] += quantity
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Remove items with zero stock from the stock dictionary
    stock = {item: qty for item, qty in stock.items() if qty > 0}

    return dict(stock), waiting
