import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = re.compile(r'\s*(?:(\d+\.\d+|\d+)|([a-zA-Z_]\w*)|((?:==|!=|<=|>=|[+\-*/<>,()]))\s*)')
    for match in pattern.finditer(source):
        kind, num, name, op = match.groups()
        if kind:
            tokens.append(('NUMBER', kind))
        elif name:
            tokens.append(('NAME', name))
        elif op:
            tokens.append(('OP', op))
    return tokens
