import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = re.compile(r'\s*(?:(\d+\.\d+|\d+)|([a-zA-Z_]\w*)|([+\-*/<>=(),])|(\.\D))')
    for match in pattern.finditer(source):
        if match.group(1):
            tokens.append(('NUMBER', match.group(1)))
        elif match.group(2):
            tokens.append(('NAME', match.group(2)))
        elif match.group(3):
            tokens.append(('OP', match.group(3)))
        else:
            raise ValueError("Invalid character encountered")
    return tokens
