def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    def pad_cell(cell: str, width: int, align: str) -> str:
        if align == 'l':
            return cell.ljust(width)
        elif align == 'r':
            return cell.rjust(width)
        else:  # align == 'c'
            spaces = width - len(cell)
            left_spaces = spaces // 2
            right_spaces = spaces - left_spaces
            return ' ' * left_spaces + cell + ' ' * right_spaces

    formatted_rows = []
    for row in rows:
        formatted_row = " | ".join(pad_cell(cell, width, aligns[i]) for i, (cell, width) in enumerate(zip(row, col_widths)))
        formatted_rows.append(formatted_row)

    return "\n".join(formatted_rows)
