from collections import defaultdict

def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    standings = defaultdict(lambda: [0, 0, 0, 0])

    for home, away, home_goals, away_goals in results:
        standings[home][2] += home_goals
        standings[away][2] += away_goals

        if home_goals > away_goals:
            standings[home][0] += 3
        elif home_goals < away_goals:
            standings[away][0] += 3
        else:
            standings[home][0] += 1
            standings[away][0] += 1

        standings[home][1] += away_goals
        standings[away][1] += home_goals

    standings_list = [(team, *data) for team, data in standings.items()]
    standings_list.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

    return standings_list

