def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and len(stack) >= 0 and max_instructions > 0:
        instruction = program[ip]
        parts = instruction.split()
        op = parts[0]

        if op == 'PUSH':
            stack.append(int(parts[1]))
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif op == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            try:
                ip = int(parts[1])
            except ValueError:
                return None
        elif op == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                try:
                    ip = int(parts[1])
                except ValueError:
                    return None
            else:
                ip += 1
        else:
            return None

        ip += 1
        max_instructions -= 1

    if max_instructions == 0:
        return None

    return stack
