def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, op in enumerate(ops):
        action, *args = op

        if action == 'deposit':
            account, amount = args
            if account in final_balances and amount > 0:
                final_balances[account] += amount
            else:
                failed.append(i)

        elif action == 'withdraw':
            account, amount = args
            if account in final_balances and amount > 0 and final_balances[account] >= amount:
                final_balances[account] -= amount
            else:
                failed.append(i)

        elif action == 'transfer':
            source, target, amount = args
            if source != target and source in final_balances and target in final_balances and amount > 0 and final_balances[source] >= amount + 2:
                final_balances[source] -= (amount + 2)
                final_balances[target] += amount
            else:
                failed.append(i)

        elif action == 'freeze':
            account, = args
            if account in final_balances:
                pass
            else:
                failed.append(i)

        elif action == 'unfreeze':
            account, = args
            if account in final_balances:
                pass
            else:
                failed.append(i)

        else:
            failed.append(i)

    return final_balances, sorted(failed)
