        return amount > 0

    def check_freeze(account):
        return final_balances[account] >= 0

    def apply_deposit(account, amount):
        final_balances[account] += amount

    def apply_withdrawal(account, amount):
        if final_balances[account] - amount < 0:
            return False
        final_balances[account] -= amount
        return True

    def apply_transfer(source, target, amount):
        if source == target:
            return False
        if not check_freeze(source) or not check_freeze(target):
            return False
        if final_balances[source] - amount - 2 < 0:
            return False
        final_balances[source] -= amount + 2
        final_balances[target] += amount
        return True

    def apply_freeze(account):
        if final_balances[account] < 0:
            return False
        final_balances[account] *= -1
        return True

    def apply_unfreeze(account):
        if final_balances[account] >= 0:
            return False
        final_balances[account] = -final_balances[account]
        return True

