def run_bank_ops(balances: Dict[str, int], ops: List[Tuple]) -> Tuple[Dict[str, int], List[int]]:
    final_balances = balances.copy()
    failed = []

    def check_account(account):
        if account not in final_balances:
            return False
        return True

    def check_amount(amount):
        return amount > 0

    def check_freeze(account):
        return final_balances[account] >= 0

    def apply_operation(index, op):
        nonlocal failed
        try:
            action, *args = op
            if action == 'deposit':
                account, amount = args
                if check_account(account) and check_amount(amount):
                    final_balances[account] += amount
            elif action == 'withdraw':
                account, amount = args
                if check_account(account) and check_amount(amount) and check_freeze(account):
                    if final_balances[account] - amount >= 0:
                        final_balances[account] -= amount
                    else:
                        raise ValueError("Insufficient funds")
            elif action == 'transfer':
                source, target, amount = args
                if check_account(source) and check_account(target) and check_amount(amount) and check_freeze(source) and check_freeze(target):
                    if source != target:
                        if final_balances[source] - amount - 2 >= 0:
                            final_balances[source] -= amount + 2
                            final_balances[target] += amount
                        else:
                            raise ValueError("Insufficient funds for transfer")
                    else:
                        raise ValueError("Source and target accounts cannot be the same")
            elif action == 'freeze':
                account, = args
                if check_account(account):
                    final_balances[account] *= -1
            elif action == 'unfreeze':
                account, = args
                if check_account(account) and final_balances[account] < 0:
                    final_balances[account] *= -1
            else:
                raise ValueError("Invalid operation")
        except Exception as e:
            failed.append(index)

    for i, op in enumerate(ops):
        apply_operation(i, op)

